# run-v2.d/rcpt.sh — nearAirV3 table 16 `rcpt` (sourced by run-v2.sh / run-v2-section.sh rcpt;
# in scope: here src out npudr lr le le3 lp fx HEAVY pass bad).
#
# Table 16 is `RcptV3.tableQ` (`Rcpt/Tables/RcptR.lean`: the repaired `tableR` — 13-bit deposit
# age, gas surplus gated by `gq` — plus the routing-index range check `q < 128`; 882
# constraints).  Its honest render `rcptTraceAlignedQ` (`Render/HonestRcptQ.lean`) is always
# `2^22` rows and is built from native execution data, so the differential runs on seeded
# *native* cases generated by the Lean exe `np-lean-render-v3-rcpt` (RenderV3Rcpt.lean): it
# evaluates the zk-formal render (accounts / walk substituted, see its doc), dumps the first
# planned+8 rows and the honest list view (+ routing intervals) as the Rust `RcptIn` JSON;
# `npudr v3rcpt-prefix` renders the same rows from that JSON; the two must be byte-identical.
# `npudr v3check … rcpt` checks all 882 constraints (900 in the export) with the honest public values at the
# compact height (see `src/v3/rcpt.rs`).
#
# Knobs: RCPT_SEEDS (1..8), RCPT_LISTS (1 3: lists per Lean case), RCPT_SAMPLE_SEEDS (1..6).
rc="$out/rcpt"; mkdir -p "$rc"
lrc="$here/.lake/build/bin/np-lean-render-v3-rcpt"
air="$out/nearAirV3.json"
rss() { awk '/Maximum resident/{printf "%.0f MB", $6/1024}' "$1" 2>/dev/null; }

echo "== rcpt: table 16 in the nearAirV3 export is tableQ"
if python3 - "$air" <<'PY'
import json, sys
t = json.load(open(sys.argv[1]))["tables"][16]
got = (t["width"], t.get("maxLog", t.get("max_log")), len(t["constraints"]))
print(f"   table 16: width {got[0]} maxLog {got[1]} constraints {got[2]} (want 263 22 900 = 882 + 18 exported multiplicity checks)")
sys.exit(0 if got == (263, 22, 900) else 1)
PY
then pass "rcpt table 16 = tableQ (263 / 22 / 882+18)"
else bad "rcpt table 16 is not tableQ"; fi

# rccheck <json> <label>: all table-16 constraints hold (honest publics, compact height)
rccheck() {
  if "$npudr" v3check "$air" rcpt "$1" >"$1.check" 2>&1; then pass "rcpt $2: $(cut -c5- "$1.check")"
  else bad "rcpt $2: constraints fail"; head -3 "$1.check"; fi
}
# rcreject <json> <label>: the rendered trace must violate a constraint
rcreject() {
  if "$npudr" v3check "$air" rcpt "$1" >"$1.check" 2>&1; then bad "rcpt $2: constraints still hold"
  else pass "rcpt $2: violated ($(head -1 "$1.check"))"; fi
}

echo "== rcpt: Lean honest render (np-lean-render-v3-rcpt) vs Rust (npudr v3rcpt-prefix)"
for nl in ${RCPT_LISTS:-1 3}; do
  for seed in ${RCPT_SEEDS:-1 2 3 4 5 6 7 8}; do
    b="$rc/lean-$seed-$nl"
    if ! /usr/bin/time -v $HEAVY "$lrc" $seed $nl "$b.json" "$b.lean.bin" >"$b.log" 2>"$b.time"; then
      bad "rcpt seed=$seed lists=$nl: np-lean-render-v3-rcpt failed"; tail -3 "$b.time"; continue; fi
    n=$(python3 -c "import struct;print(struct.unpack('<3I',open('$b.lean.bin','rb').read(12))[2])")
    if ! /usr/bin/time -v "$npudr" v3rcpt-prefix "$b.json" $n "$b.rust.bin" 2>"$b.rtime"; then
      bad "rcpt seed=$seed lists=$nl: npudr v3rcpt-prefix failed"; tail -3 "$b.rtime"; continue; fi
    if cmp -s "$b.lean.bin" "$b.rust.bin"; then
      pass "rcpt seed=$seed lists=$nl: Rust==Lean, $n rows ($(cut -d: -f2 "$b.log" | head -1 | sed 's/^ //'); Lean $(rss "$b.time"))"
    else
      bad "rcpt seed=$seed lists=$nl: Rust and Lean rows differ"
      python3 - "$b.lean.bin" "$b.rust.bin" <<'PY'
import struct, sys
a, b = open(sys.argv[1], 'rb').read(), open(sys.argv[2], 'rb').read()
w = struct.unpack('<3I', a[:12])[1]
xa, xb = struct.unpack(f'<{(len(a)-12)//4}I', a[12:]), struct.unpack(f'<{(len(b)-12)//4}I', b[12:])
d = [(k // w, k % w, xa[k], xb[k]) for k in range(min(len(xa), len(xb))) if xa[k] != xb[k]]
print(f"   {len(d)} cells differ; first (row, col, lean, rust): {d[:12]}")
PY
    fi
    rccheck "$b.json" "Lean case seed=$seed lists=$nl"
  done
done

echo "== rcpt: sampled entries (npudr v3sample rcpt) and edge inputs"
for seed in ${RCPT_SAMPLE_SEEDS:-1 2 3 4 5 6}; do
  for n in 1 4; do
    f="$rc/sample-$seed-$n.json"
    "$npudr" v3sample rcpt $seed $n > "$f" || { bad "rcpt v3sample seed=$seed n=$n failed"; continue; }
    rccheck "$f" "sample seed=$seed n=$n"
  done
done
f="$rc/empty-1.json"; echo '{"lists":[{"n0":0,"n1":0,"rs":[]}],"own":3,"height":9,"bgp":0}' > "$f"
rccheck "$f" "one empty list"
f="$rc/empty-3.json"; echo '{"lists":[{"rs":[]},{"rs":[]},{"rs":[]}],"own":3,"height":9,"bgp":7}' > "$f"
rccheck "$f" "three empty lists"

echo "== rcpt: broken entries must violate a constraint"
base="$rc/lean-1-3.json"
[ -s "$base" ] || base="$rc/sample-1-4.json"
# mutate <name> <python on `r` (first receipt) / `d` (whole input)>
mutate() {
  local f="$rc/neg-$1.json"
  python3 - "$base" "$f" "$2" <<'PY'
import json, sys
d = json.load(open(sys.argv[1]))
rs = [r for l in d["lists"] for r in l["rs"]]
r = rs[0]
exec(sys.argv[3])
json.dump(d, open(sys.argv[2], "w"))
PY
  echo "$f"
}
f=$(mutate q127 'r["q"] = 127'); rccheck "$f" "q = 127 (largest 7-bit index)"
f=$(mutate q128 'r["q"] = 128'); rcreject "$f" "q = 128 (qBoundR)"
f=$(mutate age8192 'r["tprev"] = 2013265921 - 8192'); rcreject "$f" "deposit age r - tprev = 2^13"
f=$(mutate ge 'r["ge"] = not r["ge"]'); rcreject "$f" "flipped ge"
f=$(mutate hr 'r["hr"] = not r["hr"]'); rcreject "$f" "flipped refund flag"
f=$(mutate sys 'r["sys"] = not r["sys"]'); rcreject "$f" "flipped system flag"
f=$(mutate own 'd["own"] = d["own"] + 1'); rccheck "$f" "other own (publics follow the input)"
f=$(mutate cnt 'd["lists"][0]["rs"] = d["lists"][0]["rs"] + d["lists"][0]["rs"][:1]'); rccheck "$f" "duplicated receipt (local rows stay legal)"
